/* v31.xx (cw-partylook5), the critic on v31.43 (46 52 64): "the prompt grew to about 30px and is now louder than the 32px title, set it to 20px f-cond 700 in tx-1", "the X right edge is 8px off the prompt right edge". The any-key prompt is body size (20px), so the title leads; the corner X sits on the same 32px right line as the prompt; the table heads are 16px labels. Restyle only; the prompt stays the live any-key footer */
body #attract[style*="block"]:has(.arcpage[style*="block"]) .attpress, body #attract[style*="block"]:has(.arcover[style*="block"]) .attpress{ font-size:calc(var(--fs-body) * var(--attz,1)); font-weight:700; }
body #attract .arcpage::after{ right:calc(var(--sp-4) * var(--attz,1)); }
body #attract .arcpage th{ font-size:calc(var(--fs-label) * var(--attz,1)); }

check:
{v:'VER',what:'the any-key prompt is body size (20px) so the title leads, and the corner X shares the prompt right line (critic 46 52 64)',
 run:function(){
   if(typeof arcadeAttEl!=='function'||typeof attEl!=='function') return 'SKIP: no arcade here';
   var d, wasDisp, pg, pr, fs, xr, mr, z, res=null;
   try{
     __topClear(); __runPrep();
     d=attEl(); wasDisp=d.style.display; d.style.display='block';
     try{ if(typeof attZ==='function') attZ(d); }catch(_z){}
     pg=arcadeAttEl('arcpage'); pg.style.display='block';
     pr=d.querySelector('.attpress'); if(!pr) return 'SKIP: no attpress';
     z=parseFloat(getComputedStyle(d).getPropertyValue('--attz'))||1;
     fs=parseFloat(getComputedStyle(pr).fontSize);
     if(fs>20.5*z+0.01) return 'the any-key prompt is '+fs+'px, over the 20px body size (zoom '+z+')';
     xr=getComputedStyle(pg,'::after').right; mr=getComputedStyle(pr).marginRight;
     if(xr!==mr) return 'the corner X right edge is '+xr+' but the prompt right margin is '+mr;
     return res;
   } finally {
     try{ pg.style.display='none'; d.style.display=wasDisp; }catch(_f){}
     __topClear();
   } }},
